        self.assertEqual(pennywise.parse("2024-01-01 RENT -1")[0].category, "rent")

    def test_category_case_pairs_lower_misses_are_one_category(self):
        entries = pennywise.parse("2024-01-01 Straße -1\n2024-01-02 STRASSE -2\n2024-01-03 strasse -3")
        self.assertEqual([e.category for e in entries], ["straße", "strasse", "strasse"])
        # one group, shown as the lower() of the first spelling seen
        self.assertEqual(pennywise.by_category(entries), {"straße": Decimal(-6)})
        self.assertEqual(pennywise.by_category(entries[1:]), {"strasse": Decimal(-5)})

    def test_displayed_category_is_lower_case(self):
        for text in ("Straße", "STRASSE", "ΣΑΣ", "İSTANBUL", "ꭰꭱ", "Ꭰ"):
            c = pennywise.parse("2024-01-01 %s 1" % text)[0].category
            self.assertEqual(c, text.lower())
            self.assertTrue(c.islower())

    def test_cherokee_category_stays_lower_case(self):
        for text in ("ꭰꭱ", "ᎠᎡ"):
            c = pennywise.parse("2024-01-01 %s 1" % text)[0].category
            self.assertEqual(c, "ꭰꭱ")
            self.assertTrue(c.islower())

    def test_final_sigma_and_ligature_kept_in_display(self):
        self.assertEqual(pennywise.parse("2024-01-01 Λογαριασμός 1")[0].category, "λογαριασμός")
        self.assertEqual(pennywise.parse("2024-01-01 ﬁsh 1")[0].category, "ﬁsh")

    def test_by_category_groups_on_casefold_but_shows_lower(self):
        entries = pennywise.parse("2024-01-01 ꭰꭱ 1\n2024-01-02 ᎠᎡ 2\n2024-01-03 ﬁsh 4\n2024-01-04 FISH 8")
        self.assertEqual(pennywise.by_category(entries), {"ꭰꭱ": Decimal(3), "ﬁsh": Decimal(12)})

    def test_filter_category_uses_casefold(self):
        entries = pennywise.parse("2024-01-01 Straße -1\n2024-01-02 food -2")
        for q in ("STRASSE", "straße", "Strasse"):
            self.assertEqual(pennywise.filter_entries(entries, category=q), entries[:1])
